import React from "react";
import { motion } from "framer-motion";
const Button = ({ children, onClick }) => (
  <button
    onClick={onClick}
    className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition"
  >
    {children}
  </button>
);

export default function WelcomePage({ onGetStarted }) {
  return (
    <div className="flex items-center justify-center min-h-screen bg-gradient-to-br from-purple-600 via-pink-500 to-orange-400 p-6">
      <motion.div
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.7 }}
        className="bg-white shadow-2xl rounded-3xl max-w-3xl w-full p-10 text-center"
      >
        <motion.h1
          className="text-4xl md:text-5xl font-bold text-gray-800 mb-6"
          initial={{ scale: 0.9 }}
          animate={{ scale: 1 }}
          transition={{ duration: 0.6 }}
        >
          🔒 Secure E-Diary
        </motion.h1>
        <p className="text-gray-600 text-lg leading-relaxed mb-10">
          Keep your thoughts safe, encrypted, and accessible anywhere.  
          With biometric authentication, context-aware AI, and colorful role-based dashboards,
          your personal and academic entries remain private yet powerful.  
        </p>
        <Button
          onClick={onGetStarted}
          className="px-8 py-4 rounded-full text-lg font-semibold shadow-lg bg-gradient-to-r from-purple-500 to-pink-500 hover:from-purple-600 hover:to-pink-600 transition-all"
        >
          🚀 Get Started
        </Button>
      </motion.div>
    </div>
  );
}
